@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=Crimson+Text:wght@400;600;700&family=Inter:wght@400;500;600;700&display=swap');
:root{--ink:#0b0a09;--panel:#171310;--panel2:#211a15;--gold:#c9a66b;--goldbright:#f2d89b;--blood:#8c2623;--text:#e6dccb;--muted:#9a8974;--line:rgba(196,158,99,.3);--serif:'Cinzel',Georgia,serif;--body:'Crimson Text',Georgia,serif;--ui:'Inter',Arial,sans-serif}
*{box-sizing:border-box}html,body,#app{margin:0;width:100%;height:100%;overflow:hidden;background:#080807;color:var(--text);font-family:var(--ui);user-select:none}button,input{font:inherit}button{color:inherit}#app{position:relative;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block;background:#12100e}#vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 35%,rgba(5,4,4,.34) 72%,rgba(4,3,3,.82) 125%);z-index:1}.hidden{display:none!important}
/* overall mood */
.screen{position:absolute;inset:0;z-index:8;display:none;align-items:center;justify-content:center;overflow:auto;background:radial-gradient(ellipse at 50% 45%,rgba(25,19,15,.5),rgba(7,6,6,.86) 76%);backdrop-filter:blur(2px);animation:screenIn .45s ease both}.screen.active{display:flex}@keyframes screenIn{from{opacity:0}to{opacity:1}}.screen:before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.17;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E")}
#screen-main{background:linear-gradient(90deg,rgba(8,7,6,.22),rgba(8,7,6,.55) 40%,rgba(8,7,6,.8)),linear-gradient(0deg,rgba(5,4,3,.9),transparent 25%,transparent 75%,rgba(5,4,3,.45)}.menu-fog{position:absolute;inset:0;background:radial-gradient(ellipse at 26% 57%,rgba(117,52,29,.17),transparent 35%),radial-gradient(ellipse at 70% 70%,rgba(90,83,103,.13),transparent 33%);mix-blend-mode:screen;animation:fogDrift 18s ease-in-out infinite alternate}@keyframes fogDrift{to{transform:translate(3%, -2%) scale(1.05);filter:blur(8px)}}.title-block{position:relative;width:min(560px,90vw);text-align:center;margin-left:clamp(0px,34vw,620px);padding:30px 36px 34px;background:linear-gradient(90deg,transparent,rgba(12,10,9,.78) 15%,rgba(12,10,9,.78) 85%,transparent);text-shadow:0 2px 16px #000}.title-rune{color:var(--gold);font-size:20px;text-shadow:0 0 20px #c0853d;animation:pulse 3s ease-in-out infinite}@keyframes pulse{50%{opacity:.55;text-shadow:0 0 34px #ffb84f}}.game-title{font:700 clamp(46px,6.8vw,83px)/1 var(--serif);letter-spacing:.18em;margin:12px -0.18em 5px 0;color:#e0d1b3;background:linear-gradient(#fff5dc,#c8a878 65%,#775c3d);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 5px 4px #000)}.title-rule{display:flex;align-items:center;gap:14px;justify-content:center;color:#c4a26e;font:500 12px var(--serif);letter-spacing:.35em}.title-rule span{height:1px;width:62px;background:linear-gradient(90deg,transparent,#ae8653)}.title-rule span:last-child{transform:rotate(180deg)}.title-tag{font:italic 20px var(--body);color:#c1b19b;margin:25px 0 30px}.menu-buttons{width:242px;margin:auto;display:grid;gap:8px}.btn{position:relative;min-height:43px;padding:10px 24px;border:1px solid rgba(177,145,98,.3);background:linear-gradient(110deg,rgba(36,28,21,.78),rgba(19,15,12,.87));font:500 11px var(--serif);letter-spacing:.15em;text-transform:uppercase;cursor:pointer;transition:.22s;color:#b9a990;clip-path:polygon(5% 0,95% 0,100% 50%,95% 100%,5% 100%,0 50%)}.btn:hover:not(:disabled){color:#fff1d2;border-color:#c49c64;background:linear-gradient(110deg,rgba(102,66,34,.5),rgba(44,30,20,.96));box-shadow:0 0 24px rgba(183,125,58,.15);transform:translateY(-1px)}.btn:disabled{opacity:.35;cursor:not-allowed}.btn.primary{border-color:rgba(195,153,95,.65);color:#e2c99e;background:linear-gradient(105deg,rgba(84,46,26,.78),rgba(39,26,19,.94));box-shadow:inset 0 0 20px rgba(190,122,56,.08)}.btn.ghost{background:transparent}.btn.small{min-height:34px;padding:8px 19px;font-size:10px}.save-meta{font:12px var(--body);color:#847563;margin-top:22px}.menu-footer{position:absolute;bottom:24px;left:0;right:0;text-align:center;color:#766a5b;font:11px var(--serif);letter-spacing:.12em}.menu-footer .sep{color:#ac8151;margin:0 13px}
/* class select */
#screen-select{flex-direction:column;justify-content:flex-start;padding:clamp(22px,5vh,48px) 5vw 22px;background:linear-gradient(135deg,rgba(9,8,7,.94),rgba(19,14,12,.94) 55%,rgba(8,7,6,.96))}.panel-head{text-align:center;position:relative;margin-bottom:24px}.eyebrow,.panel-eyebrow{font:10px var(--serif);letter-spacing:.3em;color:#ac8758;text-transform:uppercase}.panel-head h2{font:600 clamp(25px,3vw,38px) var(--serif);letter-spacing:.05em;margin:9px 0 6px;color:#dfd1b9}.panel-head .sub{font:17px var(--body);font-style:italic;color:#a89a86;margin:0}.class-grid{position:relative;display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:12px;width:min(1140px,100%);margin:0 auto 24px}.class-card{position:relative;min-height:clamp(240px,36vh,340px);overflow:hidden;border:1px solid rgba(175,144,97,.23);background:linear-gradient(160deg,rgba(36,28,22,.86),rgba(12,10,9,.95));cursor:pointer;transition:.28s;display:flex;flex-direction:column;align-items:center;text-align:center;padding:0 13px 15px}.class-card:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 30%,rgba(5,4,4,.95) 75%)}.class-card:hover,.class-card.selected{transform:translateY(-5px);border-color:#c59e68;box-shadow:0 0 30px rgba(176,116,54,.16)}.class-card.selected{background:linear-gradient(160deg,rgba(75,48,30,.8),rgba(15,11,9,.98))}.class-art{height:clamp(125px,20vh,195px);width:100%;position:relative;margin:0 -13px 0;align-self:stretch}.class-art canvas{width:100%;height:100%}.class-name{font:600 16px var(--serif);letter-spacing:.1em;color:#dfcca8;position:relative;margin:4px 0 5px}.class-tagline{font:italic 14px var(--body);color:#b18a5d;position:relative}.class-desc{font:13px/1.35 var(--body);color:#9e9485;position:relative;margin:9px 0 11px}.class-traits{font:9px var(--ui);letter-spacing:.07em;color:#847667;position:relative;margin-top:auto}.class-traits span{display:inline-block;margin:2px 2px;padding:4px 5px;border:1px solid rgba(180,147,101,.18)}.select-footer{position:relative;display:flex;align-items:end;justify-content:space-between;width:min(1140px,100%);gap:20px}.name-field{display:flex;flex-direction:column;gap:7px}.name-field label{font:9px var(--serif);letter-spacing:.2em;color:#a88b63}.name-field input{width:260px;max-width:45vw;color:#e1d3bc;background:rgba(4,4,3,.6);border:1px solid rgba(177,145,98,.35);padding:12px 14px;outline:none;font:16px var(--body)}.name-field input:focus{border-color:#bd985f}.select-actions{display:flex;gap:12px}.select-actions .btn{min-width:150px}
/* cinematic */
.cinematic{background:#050505}.cine-art{position:absolute;inset:0;overflow:hidden;background:linear-gradient(#111822,#29252a 53%,#170e0b)}.cine-sky{position:absolute;inset:0;background:radial-gradient(ellipse at 70% 36%,rgba(162,122,91,.16),transparent 35%),linear-gradient(180deg,transparent 48%,rgba(12,8,7,.84))}.cine-moon{position:absolute;right:22%;top:12%;width:clamp(90px,14vw,200px);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 42% 42%,#c9b9a3 0%,#8c847d 40%,#50494a 70%,transparent 72%);box-shadow:0 0 60px rgba(194,157,126,.19);opacity:.68}.cine-spire{position:absolute;bottom:21%;background:#090909;clip-path:polygon(43% 0,51% 11%,56% 34%,100% 100%,0 100%,36% 35%)}.cine-spire.s1{height:65%;width:19%;left:10%}.cine-spire.s2{height:47%;width:16%;left:30%;filter:brightness(.7)}.cine-spire.s3{height:75%;width:21%;right:5%;filter:brightness(.72)}.cine-fire{position:absolute;bottom:20%;left:34%;width:27%;height:20%;background:radial-gradient(ellipse,rgba(244,111,39,.32),transparent 70%);filter:blur(22px);animation:pulse 2s infinite}.cine-ash{position:absolute;inset:0}.cine-bars{height:10vh;position:absolute;left:0;right:0;background:#030303;z-index:2}.cine-bars.top{top:0}.cine-bars.bottom{bottom:0}.cine-text{z-index:3;position:absolute;top:56%;left:50%;transform:translate(-50%,-50%);width:min(750px,86vw);text-align:center;text-shadow:0 3px 12px #000}.cine-chapter{font:10px var(--serif);letter-spacing:.38em;color:#c59b66;margin-bottom:13px}.cine-text h3{font:500 clamp(26px,4vw,47px) var(--serif);color:#e2d3b9;margin:0 0 16px}.cine-text p{font:italic clamp(18px,2.2vw,24px)/1.55 var(--body);color:#d3c5b0;min-height:70px}.cine-actions{z-index:4;position:absolute;bottom:13%;right:8%;display:flex;gap:12px}
/* HUD */
#hud{position:absolute;inset:0;z-index:4;pointer-events:none}.hud-top-left{position:absolute;top:25px;left:28px;display:flex;align-items:center;gap:13px}.portrait-frame{width:62px;height:62px;border:2px solid #93734d;border-radius:50%;background:#19120e;box-shadow:0 0 0 4px rgba(7,6,5,.75),0 0 18px #000;position:relative}.portrait-frame canvas{width:100%;height:100%;border-radius:50%}.lvl-badge{position:absolute;right:-6px;bottom:-4px;background:#282018;border:1px solid #c6a066;border-radius:50%;width:21px;height:21px;text-align:center;font:10px/19px var(--serif);color:#ead4a6}.char-meta{min-width:150px;text-shadow:0 2px 4px #000}.char-name{font:600 15px var(--serif);color:#e4d4b8;letter-spacing:.07em}.char-class{font:10px var(--ui);letter-spacing:.14em;text-transform:uppercase;color:#b09672;margin-top:3px}.bar{height:4px;background:#271c16;border:1px solid rgba(0,0,0,.7);position:relative;overflow:hidden}.xp-bar{width:135px;margin-top:7px}.bar .fill{height:100%;transition:width .25s}.xp-bar .fill{background:#c9a054}.xp-bar span{position:absolute;inset:-1px 0;text-align:center;font:8px/4px var(--ui);color:#fff;text-shadow:0 1px 2px #000;opacity:.75}.region-banner{position:absolute;top:26px;left:50%;transform:translateX(-50%);text-align:center;text-shadow:0 2px 7px #000;opacity:0;transition:opacity 1s}.region-banner.show{opacity:1}.region-name{font:500 15px var(--serif);letter-spacing:.21em;color:#e0d1b3}.region-sub{font:italic 12px var(--body);color:#af9874;margin-top:3px}.hud-top-right{position:absolute;top:22px;right:25px;display:flex;align-items:center;gap:11px;flex-direction:column}.minimap-frame{width:148px;height:148px;padding:5px;border-radius:50%;background:radial-gradient(circle,#26211b,#090807 70%);border:1px solid rgba(178,144,96,.65);box-shadow:0 0 0 4px rgba(7,6,5,.62),0 2px 16px #000;position:relative}.minimap-frame canvas{width:100%;height:100%;border-radius:50%;opacity:.94}.minimap-ring{pointer-events:none;position:absolute;inset:0;border-radius:50%;border:5px solid rgba(0,0,0,.55)}.minimap-label{position:absolute;bottom:-9px;left:50%;transform:translateX(-50%);font:8px var(--serif);letter-spacing:.16em;background:#110e0b;border:1px solid #6f5637;color:#c7a773;padding:3px 8px;white-space:nowrap}.currency-row{font:11px var(--ui);text-shadow:0 2px 3px #000;color:#e4d6be}.currency-row .coin{color:#d9b760;margin-right:4px}.currency-row .essence{color:#76bbcd;margin-left:12px;margin-right:4px}.quest-tracker{position:absolute;top:205px;right:27px;width:208px;text-shadow:0 2px 4px #000}.qt-head{font:9px var(--serif);letter-spacing:.24em;text-transform:uppercase;color:#b4915e;border-bottom:1px solid rgba(190,151,98,.3);padding-bottom:6px;margin-bottom:7px}.qt-title{font:600 13px var(--serif);color:#e3d4b9}.qt-objectives{font:12px var(--body);color:#b2a592;padding-left:17px;margin:6px 0}.qt-objectives li{margin:3px 0}.qt-objectives li.done{color:#88a57e;text-decoration:line-through}.globe-wrap{position:absolute;bottom:29px;display:flex;flex-direction:column;align-items:center;gap:4px}.globe-wrap.left{left:36px}.globe-wrap.right{right:36px}.globe{position:relative;width:94px;height:94px;border:3px solid #8a704e;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 35% 28%,#302b27,#080707 72%);box-shadow:0 0 0 5px rgba(8,6,5,.85),0 0 26px #000, inset 0 0 15px #000}.globe:before{content:"";position:absolute;inset:-2px;border-radius:50%;z-index:2;border:2px solid rgba(226,199,147,.2)}.globe-liquid{position:absolute;bottom:0;left:-15%;width:130%;height:100%;transition:height .25s;clip-path:polygon(0 12%,12% 9%,25% 12%,38% 8%,51% 11%,63% 8%,76% 12%,88% 9%,100% 12%,100% 100%,0 100%);animation:liquid 4s ease-in-out infinite alternate}.globe-liquid.health{background:linear-gradient(100deg,#571616,#b42c27 40%,#691718);box-shadow:0 0 20px #ba3526}.globe-liquid.resource{background:linear-gradient(100deg,#51371a,#c18637 40%,#70501d)}@keyframes liquid{to{transform:translateX(4%) translateY(3%)}}.globe-shine{position:absolute;z-index:3;inset:5px 13px 5px 8px;border-radius:50%;background:linear-gradient(110deg,rgba(255,255,255,.12),transparent 35%,transparent 67%,rgba(255,255,255,.06));box-shadow:inset 0 0 15px rgba(255,255,255,.09)}.globe-value{position:absolute;z-index:4;inset:0;display:grid;place-items:center;font:600 18px var(--serif);color:#fff1d8;text-shadow:0 2px 5px #000}.globe-caption{font:8px var(--serif);letter-spacing:.19em;color:#c5b393;text-shadow:0 2px 4px #000}.action-bar{position:absolute;bottom:33px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;pointer-events:auto}.abilities{display:flex;gap:5px;padding:6px;background:linear-gradient(180deg,rgba(22,17,14,.91),rgba(8,7,6,.95));border:1px solid rgba(171,136,87,.43);box-shadow:0 4px 18px #000;border-radius:3px}.ability-slot,.potion-slot{width:48px;height:48px;border:1px solid rgba(167,139,96,.5);background:radial-gradient(circle at 50% 42%,#3c3024,#100e0b 72%);position:relative;display:grid;place-items:center;cursor:pointer;transition:.16s;box-shadow:inset 0 0 12px #000}.ability-slot:hover,.potion-slot:hover{border-color:#f0ca82;box-shadow:0 0 12px rgba(220,161,71,.28),inset 0 0 12px #000}.ability-icon{font-size:24px;filter:drop-shadow(0 2px 3px #000)}.ability-key{position:absolute;top:2px;left:4px;font:9px var(--ui);color:#d4be99;text-shadow:0 1px 2px #000}.ability-cooldown{position:absolute;inset:0;background:rgba(3,3,3,.7);display:grid;place-items:center;font:12px var(--ui);color:#e0d6c6}.ability-name{position:absolute;bottom:-13px;white-space:nowrap;font:8px var(--ui);color:#ad9e89;text-shadow:0 2px 3px #000;opacity:.8}.potion-slot{width:45px;height:45px;border-radius:50%;border-color:#8f4e3e}.potion-icon{font-size:21px;color:#cb7770}.potion-count{position:absolute;bottom:1px;right:4px;font:10px var(--ui);color:#fff}.bar-actions{display:flex;gap:4px;margin-left:7px}.mini-btn{width:34px;height:34px;border:1px solid rgba(165,137,94,.42);background:rgba(14,11,9,.88);color:#c9b99d;font-size:15px;cursor:pointer;transition:.16s}.mini-btn:hover{color:#fff0d3;border-color:#cb9e60;background:#302317}.hint-bar{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);font:9px var(--ui);letter-spacing:.05em;color:rgba(216,200,175,.51);white-space:nowrap;text-shadow:0 1px 4px #000}.toast-layer{position:absolute;top:22%;left:50%;transform:translateX(-50%);display:grid;gap:8px;justify-items:center}.toast{font:500 12px var(--serif);letter-spacing:.1em;color:#e1c590;text-shadow:0 2px 6px #000;animation:toastIn .3s ease,toastOut .7s ease 3.2s forwards}.toast.important{font-size:16px;color:#f1d89e}.toast.alert{color:#e0806a}@keyframes toastIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes toastOut{to{opacity:0;transform:translateY(-14px)}}.loot-log{position:absolute;bottom:137px;left:50%;transform:translateX(-50%);font:10px var(--serif);letter-spacing:.08em;text-shadow:0 2px 4px #000}.loot-line{animation:toastOut 3s forwards}.loot-line.Common{color:#d4cbb9}.loot-line.Magic{color:#78acd9}.loot-line.Rare{color:#e5cb61}.loot-line.Epic{color:#bd79dc}.loot-line.Legendary{color:#df914a}.loot-line.Mythic{color:#e98779}.boss-bar{position:absolute;bottom:139px;left:50%;transform:translateX(-50%);width:min(540px,64vw);text-align:center;text-shadow:0 2px 4px #000}.boss-name{font:600 16px var(--serif);letter-spacing:.13em;color:#e4d2b0}.boss-sub{font:italic 12px var(--body);color:#b19b7c;margin:2px 0 7px}.boss-hp{height:9px;border:1px solid #a17248;background:#170c0c;box-shadow:0 1px 10px #000}.boss-hp .fill{background:linear-gradient(90deg,#7f1719,#d64536,#792022);box-shadow:0 0 8px #c32620}.boss-phases{display:flex;justify-content:space-around;position:absolute;left:0;right:0;top:47px;pointer-events:none}.boss-phases i{height:9px;width:1px;background:#e6c58e;opacity:.8}.interact-prompt{position:absolute;left:50%;top:67%;transform:translate(-50%,-50%);background:rgba(11,9,7,.85);border:1px solid rgba(199,159,99,.6);padding:8px 14px;color:#ddc8a3;font:12px var(--body)}.interact-prompt b{border:1px solid #ad8b59;padding:2px 6px;margin-right:7px;font:10px var(--ui)}.combat-tip{position:absolute;left:50%;top:58%;transform:translateX(-50%);font:italic 15px var(--body);color:#edd3a0;text-shadow:0 2px 5px #000}.damage-number{position:absolute;pointer-events:none;font:700 16px var(--serif);color:#fff1ce;text-shadow:0 2px 3px #3a0908;animation:damageFloat .8s ease-out forwards}.damage-number.crit{font-size:23px;color:#ffd65f}.damage-number.player-dmg{color:#e48b71;font-size:18px}@keyframes damageFloat{from{opacity:0;transform:translate(-50%,0) scale(.8)}20%{opacity:1}to{opacity:0;transform:translate(-50%,-48px) scale(1.1)}}#levelup-fx{position:absolute;z-index:7;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;background:radial-gradient(ellipse,rgba(214,171,94,.2),transparent 50%);animation:levelFade 2.8s forwards;text-shadow:0 2px 8px #000}.lu-ring{position:absolute;width:240px;height:240px;border-radius:50%;border:1px solid rgba(239,204,132,.8);box-shadow:0 0 50px #cda45c,inset 0 0 40px rgba(255,208,112,.3);animation:ringExpand 1.8s ease-out forwards}.lu-text{font:600 27px var(--serif);color:#ffe7b0;letter-spacing:.22em}.lu-sub{font:italic 17px var(--body);color:#d7c3a0;margin-top:8px}@keyframes ringExpand{to{transform:scale(2.4);opacity:0}}@keyframes levelFade{0%,75%{opacity:1}100%{opacity:0}}
/* Panels */
#panel-layer{position:absolute;inset:0;z-index:12;display:grid;place-items:center}.panel-backdrop{position:absolute;inset:0;background:rgba(3,3,3,.72);backdrop-filter:blur(5px)}.game-panel{position:relative;width:min(870px,92vw);max-height:88vh;overflow:hidden;background:linear-gradient(145deg,rgba(34,27,22,.98),rgba(13,11,10,.99));border:1px solid rgba(186,148,91,.57);box-shadow:0 20px 90px #000,inset 0 0 40px rgba(107,73,43,.12);padding:25px 30px 27px;animation:panelIn .22s ease}.game-panel:before{content:"";position:absolute;inset:5px;border:1px solid rgba(180,143,89,.13);pointer-events:none}.panel-header{position:relative;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(179,142,88,.31);padding-bottom:13px;margin-bottom:18px}.panel-header h2{font:500 25px var(--serif);color:#e2d1b4;margin:5px 0 0}.panel-eyebrow{font-size:8px}.close-btn{border:1px solid rgba(171,138,91,.4);background:rgba(0,0,0,.2);color:#bda982;width:31px;height:31px;cursor:pointer}.close-btn:hover{border-color:#e3b975;color:#fff}.panel-body{position:relative;max-height:calc(88vh - 110px);overflow-y:auto;scrollbar-color:#65503a #15100c;scrollbar-width:thin}.panel-body::-webkit-scrollbar{width:5px}.panel-body::-webkit-scrollbar-thumb{background:#725a3c}.inventory-layout{display:grid;grid-template-columns:1fr 1.2fr;gap:24px}.equip-title,.bag-title{font:10px var(--serif);letter-spacing:.2em;color:#b59562;margin:0 0 10px}.equip-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.equip-slot{min-height:68px;border:1px solid rgba(164,132,88,.28);background:rgba(5,4,4,.42);display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;cursor:pointer;padding:7px}.equip-slot:hover{border-color:#c69d60}.equip-slot.equipped{border-color:rgba(191,155,96,.45)}.slot-label{font:8px var(--ui);color:#8f816d;text-transform:uppercase;letter-spacing:.07em}.slot-icon{font-size:20px;margin:3px}.slot-item{font:10px var(--body);text-alig