const KEY='eldoria-chronicle-v1';
export function saveGame(state){try{const clean=JSON.parse(JSON.stringify(state));localStorage.setItem(KEY,JSON.stringify(clean));return true}catch(e){console.warn('Chronicle could not be saved',e);return false}}
export function loadGame(){try{const raw=localStorage.getItem(KEY);if(!raw)return null;const data=JSON.parse(raw);if(!data||!data.character||!data.inventory||!Array.isArray(data.inventory))return null;return data}catch(e){return null}}
export function clearSave(){localStorage.removeItem(KEY)}
export function saveExists(){return !!loadGame()}

import {ENEMIES,REGIONS} from './data.js';
const TAU=Math.PI*2;
const rand=(a,b)=>a+Math.random()*(b-a), pick=a=>a[Math.floor(Math.random()*a.length)], clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const iso=(x,y)=>({x:(x-y)*.866,y:(x+y)*.5});
export class World{
 constructor(game){this.g=game;this.w=2400;this.h=1800;this.camera={x:1200,y:900,zoom:1};this.decor=[];this.entities=[];this.effects=[];this.projectiles=[];this.drops=[];this.obstacles=[];this.mapSeed=1717;this.generate();}
 generate(){let r=()=>Math.random();for(let i=0;i<320;i++){let x=rand(30,this.w-30),y=rand(30,this.h-30),d=Math.hypot(x-1200,y-900);if(d<215)continue;let type=pick(['deadtree','rock','stump','grass','torch','gravestone','shrub','bones']);this.decor.push({x,y,type,s:rand(.65,1.35),rot:rand(-.18,.18),seed:r()});}for(let i=0;i<16;i++){let a=rand(0,TAU),d=rand(190,840),x=1200+Math.cos(a)*d,y=900+Math.sin(a)*d;this.spawnEnemy(i<7?'husk':i<11?'hound':i<14?'cultist':'elite',x,y);}this.waypoint={x:1200,y:900};this.bossGate={x:2020,y:930};}
 spawnEnemy(type,x,y,extra={}){let d=ENEMIES[type];if(!d)return;let e={id:crypto.randomUUID?.()||Math.random().toString(36),type,x,y,hp:d.hp,maxHp:d.hp,alive:true,attackCd:rand(.5,2),wander:rand(0,TAU),state:'idle',stateT:0,attackT:0,hitFlash:0,phase:1, ...extra};this.entities.push(e);return e;}
 addEffect(effect){this.effects.push({...effect,age:0});}
