   ctx.save();ctx.translate(ctx.canvas.width/2,ctx.canvas.height/2);ctx.scale(z,z);ctx.translate(-cam.x,-cam.y);let origin=iso(0,0),mapW=this.w*1.732,mapH=this.h;ctx.fillStyle='#171612';ctx.fillRect(-240,-180,mapW+480,mapH+360);
