   ctx.save();ctx.lineCap='round';ctx.strokeStyle='rgba(125,103,73,.24)';ctx.lineWidth=90;ctx.beginPath();ctx.moveTo(500,1420);ctx.bezierCurveTo(740,1250,750,1060,1050,940);ctx.bezierCurveTo(1320,840,1500,1030,1740,780);ctx.stroke();ctx.strokeStyle='rgba(20,18,16,.22)';ctx.lineWidth=7;ctx.stroke();ctx.restore();
