   for(let i=0;i<21;i++){let x=((i*343+135)%mapW),y=((i*197+220)%mapH);ctx.strokeStyle='rgba(12,11,10,.5)';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+rand(7,24),y+rand(8,30));ctx.lineTo(x+rand(15,35),y+rand(14,48));ctx.stroke();}
