 drawShrine(ctx){ctx.save();let x=1200,y=900;ctx.globalAlpha=.82;ctx.fillStyle='rgba(191,142,66,.12)';ctx.beginPath();ctx.ellipse(x,y+8,78,38,0,0,TAU);ctx.fill();ctx.strokeStyle='#a48c65';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(x,y,57,29,0,0,TAU);ctx.stroke();ctx.strokeStyle='#4b4337';ctx.lineWidth=13;ctx.beginPath();ctx.ellipse(x,y,68,35,0,0,TAU);ctx.stroke();ctx.strokeStyle='#ad925c';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y,55,27,0,0,TAU);ctx.stroke();ctx.fillStyle='#171410';ctx.beginPath();ctx.ellipse(x,y,37,18,0,0,TAU);ctx.fill();ctx.restore();}
 drawGate(ctx){let g=this.bossGate;ctx.save();ctx.translate(g.x,g.y);ctx.fillStyle='rgba(148,39,26,.17)';ctx.beginPath();ctx.ellipse(0,10,110,50,0,0,TAU);ctx.fill();ctx.strokeStyle='#4c3930';ctx.lineWidth=13;ctx.beginPath();ctx.moveTo(-62,20);ctx.lineTo(-62,-72);ctx.quadraticCurveTo(0,-158,62,-72);ctx.lineTo(62,20);ctx.stroke();ctx.strokeStyle='#876343';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-48,15);ctx.lineTo(-48,-65);ctx.quadraticCurveTo(0,-137,48,-65);ctx.lineTo(48,15);ctx.stroke();ctx.fillStyle='#100a08';ctx.beginPath();ctx.moveTo(-42,14);ctx.lineTo(-42,-64);ctx.quadraticCurveTo(0,-128,42,-64);ctx.lineTo(42,14);ctx.fill();ctx.fillStyle='rgba(199,55,29,.12)';ctx.fill();for(let i=0;i<3;i++){ctx.fillStyle='#8e3f2a';ctx.fillRect(-73+i*72,-17,8,36)}ctx.restore();}
 drawDecor(ctx,o){ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.rot);let s=o.s;ctx.scale(s,s);ctx.fillStyle='rgba(0,0,0,.32)';ctx.beginPath();ctx.ellipse(0,3,18,7,0,0,TAU);ctx.fill();switch(o.type){case'deadtree':{ctx.strokeStyle='#30251d';ctx.lineCap='round';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-3,-34);ctx.lineTo(-16,-49);ctx.moveTo(-3,-34);ctx.lineTo(9,-48);ctx.lineTo(17,-61);ctx.moveTo(2,-40);ctx.lineTo(0,-58);ctx.stroke();ctx.strokeStyle='#44362a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-2,-5);ctx.lineTo(-5,-33);ctx.stroke();break}case'rock':case'bones':{ctx.fillStyle=o.type==='rock'?'#514c42':'#a3987d';ctx.beginPath();ctx.moveTo(-17,0);ctx.lineTo(-14,-12);ctx.lineTo(-5,-22);ctx.lineTo(6,-18);ctx.lineTo(15,-9);ctx.lineTo(18,0);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(255,255,255,.09)';ctx.beginPath();ctx.moveTo(-14,-11);ctx.lineTo(-5,-22);ctx.lineTo(6,-18);ctx.lineTo(0,-12);ctx.fill();break}case'stump':{ctx.fillStyle='#30241b';ctx.fillRect(-8,-18,16,19);ctx.fillStyle='#674a34';ctx.beginPath();ctx.ellipse(0,-18,9,4,0,0,TAU);ctx.fill();break}case'torch':{ctx.strokeStyle='#4e4133';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-29);ctx.stroke();ctx.fillStyle='#e69348';ctx.shadowColor='#f09843';ctx.shadowBlur=19;ctx.beginPath();ctx.ellipse(0,-34,5,9,0,0,TAU);ctx.fill();ctx.shadowBlur=0;break}case'gravestone':{ctx.fillStyle='#504a40';ctx.beginPath();ctx.moveTo(-10,0);ctx.lineTo(-9,-17);ctx.quadraticCurveTo(-9,-28,0,-28);ctx.quadraticCurveTo(9,-28,9,-17);ctx.lineTo(10,0);ctx.fill();ctx.strokeStyle='#7d715e';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-22);ctx.lineTo(0,-8);ctx.moveTo(-5,-17);ctx.lineTo(5,-17);ctx.stroke();break}case'shrub':case'grass':{ctx.fillStyle=o.type==='grass'?'#686547':'#384237';for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse((i-2)*5,-5-Math.sin(i)*4,5,10,rand(-.6,.6),0,TAU);ctx.fill()}break}}ctx.restore();}
 drawPlayer(ctx,p){ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='rgba(0,0,0,.45)';ctx.beginPath();ctx.ellipse(0,2,18,8,0,0,TAU);ctx.fill();let bob=Math.sin(p.anim*10)*1.5;ctx.translate(0,bob);ctx.rotate(p.facing||0);
   let coat=p.classId==='warrior'?'#594536':p.classId==='mage'?'#3e4c61':p.classId==='ranger'?'#47503b':p.classId==='necromancer'?'#493b50':p.classId==='paladin'?'#7d6a48':'#60403e';let skin='#bca88a';ctx.fillStyle=coat;ctx.beginPath();ctx.moveTo(-11,-17);ctx.lineTo(-9,-30);ctx.lineTo(0,-34);ctx.lineTo(10,-29);ctx.lineTo(13,-15);ctx.lineTo(10,-4);ctx.lineTo(-10,-4);ctx.closePath();ctx.fill();ctx.fillStyle='#96816a';ctx.fillRect(-9,-15,18,3);ctx.fillStyle=skin;ctx.beginPath();ctx.ellipse(0,-37,8,10,0,0,TAU);ctx.fill();ctx.fillStyle='#322b23';ctx.beginPath();ctx.arc(0,-41,8,Math.PI,0);ctx.lineTo(8,-38);ctx.lineTo(-8,-38);ctx.fill();ctx.fillStyle='#dbc99f';ctx.fillRect(2,-39,3,1);ctx.strokeStyle='#a98d60';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(8,-18);ctx.lineTo(15,-6);ctx.stroke();ctx.strokeStyle='#d2c0a0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(15,-6);ctx.lineTo(19,-28);ctx.stroke();if(p.attackAnim>0){ctx.strokeStyle='rgba(255,231,173,'+(p.attackAnim/.28*.7)+')';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-21,31,-1.2,1.2);ctx.stroke()}ctx.restore();}
 drawEnemy(ctx,e){ctx.save();ctx.translate(e.x,e.y);let d=ENEMIES[e.type],s=d.size;ctx.fillStyle='rgba(0,0,0,.44)';ctx.beginPath();ctx.ellipse(0,3,s*1.2,s*.47,0,0,TAU);ctx.fill();if(e.type==='boss'){ctx.globalAlpha=.18+Math.sin(performance.now()/250)*.06;ctx.fillStyle='#ae3322';ctx.beginPath();ctx.ellipse(0,-20,55,60,0,0,TAU);ctx.fill();ctx.globalAlpha=1}
  if(e.telegraph>0){ctx.strokeStyle=`rgba(214,74,47,${Math.min(.7,e.telegraph*1.6)})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,d.range+10,0,TAU);ctx.stroke()}
  let flash=e.hitFlash>0;ctx.fillStyle=flash?'#fff0cf':d.color;
  if(e.type==='hound'){ctx.rotate(Math.sin(e.wander)*.12);ctx.beginPath();ctx.ellipse(0,-8,14,9,0,0,TAU);ctx.fill();ctx.beginPath();ctx.moveTo(8,-11);ctx.lineTo(17,-18);ctx.lineTo(21,-9);ctx.lineTo(12,-5);ctx.fill();ctx.strokeStyle='#3d2822';ctx.lineWidth=3;for(let x of [-9,7]){ctx.beginPath();ctx.moveTo(x,-4);ctx.lineTo(x+2,3);ctx.stroke()}ctx.fillStyle='#dca36e';ctx.fillRect(16,-13,3,2)}else if(e.type==='cultist'){ctx.beginPath();ctx.moveTo(-12,0);ctx.lineTo(-8,-26);ctx.lineTo(0,-32);ctx.lineTo(9,-26);ctx.lineTo(13,0);ctx.closePath();ctx.fill();ctx.fillStyle='#d6c3a6';ctx.beginPath();ctx.arc(0,-34,7,0,TAU);ctx.fill();ctx.fillStyle='#211619';ctx.fillRect(-3,-35,7,2);ctx.strokeStyle='#795448';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(10,-22);ctx.lineTo(16,-36);ctx.stroke();ctx.fillStyle='#b64139';ctx.beginPath();ctx.arc(16,-37,3,0,TAU);ctx.fill()}else{let big=e.type==='boss'?1.7:e.type==='elite'?1.28:1;ctx.scale(big,big);ctx.fillStyle=flash?'#fff1c8':d.color;ctx.beginPath();ctx.moveTo(-11,-2);ctx.lineTo(-13,-22);ctx.lineTo(-8,-30);ctx.lineTo(-3,-33);ctx.lineTo(-1,-41);ctx.lineTo(4,-32);ctx.lineTo(10,-29);ctx.lineTo(14,-16);ctx.lineTo(12,-2);ctx.closePath();ctx.fill();ctx.fillStyle='#39322a';ctx.fillRect(-9,-5,7,8);ctx.fillRect(4,-5,7,8);ctx.fillStyle=e.type==='boss'?'#ff8b38':'#dc503b';ctx.fillRect(2,-32,3,2);ctx.strokeStyle='#574533';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-9,-23);ctx.lineTo(-17,-10);ctx.moveTo(9,-23);ctx.lineTo(16,-10);ctx.stroke();if(e.type==='boss'){ctx.strokeStyle='#a59375';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-5,-30);ctx.lineTo(-12,-47);ctx.lineTo(-16,-55);ctx.moveTo(4,-31);ctx.lineTo(12,-47);ctx.lineTo(17,-54);ctx.stroke();ctx.strokeStyle='#cbb88f';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(11,-15);ctx.lineTo(27,-7);ctx.stroke()}}
  if(e.elite||e.type==='boss'){ctx.strokeStyle=e.type==='boss'?'#d18b4e':'#c38657';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(0,-15,s+3,s+12,0,0,TAU);ctx.stroke();ctx.fillStyle='#d6c5a5';ctx.font='10px Cinzel';ctx.textAlign='center';ctx.fillText(e.type==='boss'?'✦ ELITE ✦':'ELITE',0,-s-29)}
  if(e.hitFlash>0){ctx.globalAlpha=.85;ctx.fillStyle='#efe0c6';ctx.fillRect(-13,-53,26,3);ctx.globalAlpha=1}if(e.hp<e.maxHp){ctx.fillStyle='#100b09';ctx.fillRect(-s,-s-11,s*2,3);ctx.fillStyle=e.elite?'#d39b51':'#ac4236';ctx.fillRect(-s,-s-11,s*2*Math.max(0,e.hp/e.maxHp),3)}ctx.restore();}
 drawDrop(ctx,d){ctx.save();ctx.translate(d.x,d.y+Math.sin(d.age*3)*3);ctx.fillStyle='rgba(0,0,0,.38)';ctx.beginPath();ctx.ellipse(0,5,10,4,0,0,TAU);ctx.fill();ctx.shadowColor=d.rarity==='Legendary'?'#e98e40':d.rarity==='Rare'?'#e3cf5b':d.rarity==='Magic'?'#6da4da':'#aaa';ctx.shadowBlur=12;ctx.fillStyle=d.rarity==='Legendary'?'#ec9d48':d.rarity==='Rare'?'#ddcc61':d.rarity==='Magic'?'#83b5dd':'#c7c0ad';ctx.save();ctx.rotate(Math.PI/4);ctx.fillRect(-6,-6,12,12);ctx.restore();ctx.shadowBlur=0;ctx.fillStyle='#eee1cb';ctx.font='8px Cinzel';ctx.textAlign='center';ctx.fillText(d.item.name,0,-12);ctx.restore();}
 drawEffects(ctx,dt){this.effects.forEach(f=>{let t=f.age/f.life;ctx.save();ctx.globalAlpha=Math.max(0,1-t);if(f.type==='slash'){ctx.strokeStyle=f.color||'#e4ce94';ctx.lineWidth=5*(1-t);ctx.beginPath();ctx.arc(f.x,f.y,f.radius||38,f.a-1,f.a+1);ctx.stroke()}else if(f.type==='burst'){ctx.strokeStyle=f.color||'#db713d';ctx.lineWidth=4*(1-t);ctx.beginPath();ctx.arc(f.x,f.y,(f.radius||65)*t,0,TAU);ctx.stroke();ctx.fillStyle=f.color||'#db713d';ctx.globalAlpha=.13*(1-t);ctx.beginPath();ctx.arc(f.x,f.y,(f.radius||65)*t,0,TAU);ctx.fill()}else if(f.type==='beam'){ctx.strokeStyle=f.color||'#e3c181';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=14;ctx.lineWidth=f.width||5;ctx.beginPath();ctx.moveTo(f.x,f.y);ctx.lineTo(f.x2,f.y2);ctx.stroke()}else if(f.type==='impact'){ctx.fillStyle=f.color||'#fff1c5';ctx.beginPath();ctx.arc(f.x,f.y,13*(1-t),0,TAU);ctx.fill()}else if(f.type==='telegraph'){ctx.strokeStyle='#de5343';ctx.lineWidth=2;ctx.beginPath();ctx.arc(f.x,f.y,f.radius*t,0,TAU);ctx.stroke()}ctx.restore()});}
 drawTelegraphs(ctx){this.entities.forEach(e=>{if(e.telegraph>0&&e.alive){ctx.save();ctx.globalAlpha=.25;ctx.fillStyle='#c43e30';ctx.beginPath();ctx.ellipse(e.targetX??this.g.player.x,e.targetY??this.g.player.y,26,13,0,0,TAU);ctx.fill();ctx.restore()}})}
 drawNightAtmosphere(ctx){let W=this.w*1.732,H=this.h;ctx.save();let g=ctx.createRadialGradient(1200,900,80,1200,900,1100);g.addColorStop(0,'rgba(9,12,16,0)');g.addColorStop(.7,'rgba(12,13,18,.07)');g.addColorStop(1,'rgba(7,8,13,.4)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.restore();}
 update(dt){let p=this.g.player;if(!p)return;let cam=this.camera;cam.x+=(p.x-cam.x)*Math.min(1,dt*5);cam.y+=(p.y-cam.y)*Math.min(1,dt*5);this.effects.forEach(f=>f.age+=dt);this.effects=this.effects.filter(f=>f.age<f.life);this.projectiles.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.target&&b.target.alive&&b.homing){let dx=b.target.x-b.x,dy=b.target.y-b.y,n=Math.hypot(dx,dy)||1;b.vx+=dx/n*210*dt;b.vy+=dy/n*210*dt;let s=Math.hypot(b.vx,b.vy);b.vx=b.vx/s*b.speed;b.vy=b.vy/s*b.speed}for(let e of this.entities){if(e.alive&&Math.hypot(b.x-e.x,b.y-e.y)<(b.radius||10)+12){this.g.combat.hitEnemy(e,b.damage,b.crit);b.life=0;break}}if(b.life<=0)this.addEffect({type:'impact',x:b.x,y:b.y,color:b.color,life:.2})});this.projectiles=this.projectiles.filter(b=>b.life>0);this.drops.forEach(d=>d.age+=dt);this.entities.forEach(e=>this.updateEnemy(e,dt));this.entities=this.entities.filter(e=>e.alive||e.deadT<3);}
 updateEnemy(e,dt){if(!e.alive){e.deadT=(e.deadT||0)+dt;return}let p=this.g.player,d=ENEMIES[e.type],dist=Math.hypot(p.x-e.x,p.y-e.y);e.hitFlash=Math.max(0,e.hitFlash-dt);e.attackCd-=dt;e.stateT-=dt;if(e.type==='boss'){let hp=e.hp/e.maxHp,newPhase=hp<.34?3:hp<.67?2:1;if(newPhase>e.phase){e.phase=newPhase;this.g.ui.toast(newPhase===2?'The Warden’s armor fractures.':'The Warden calls the ash!',true);this.g.ui.bossPhase(newPhase)} }
