export function createPlayer(classId='warrior',name='Wanderer',saved={}){
 const p={x:1200,y:900,facing:0,anim:0,attackAnim:0,roll:0,invuln:0,level:1,xp:0,xpNext:100,gold:0,essence:0,potions:3,maxHp:120,hp:120,maxResource:100,resource:100,classId,name,damage:16,speed:178,crit:.08,armor:0, ...saved};
 p.hp=Math.min(p.hp,p.maxHp);p.resource=Math.min(p.resource,p.maxResource);return p;
}
export function movePlayer(p,input,dt,world){let dx=input.x,dy=input.y,n=Math.hypot(dx,dy);if(n>1){dx/=n;dy/=n}if(n>.08){p.x+=dx*p.speed*dt;p.y+=dy*p.speed*dt;p.facing=Math.atan2(dy,dx);p.anim+=dt}p.x=Math.max(40,Math.min(world.w-40,p.x));p.y=Math.max(40,Math.min(world.h-40,p.y));p.attackAnim=Math.max(0,p.attackAnim-dt);p.invuln=Math.max(0,p.invuln-dt);p.roll=Math.max(0,p.roll-dt);}

const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export class Combat{
 constructor(game){this.g=game;this.cooldowns=Array(6).fill(0);this.buff=0}
 nearest(range=110){let p=this.g.player;return this.g.world.entities.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<=range).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0]}
 attack(){let p=this.g.player;if(this.g.paused||this.g.dead)return;let target=this.nearest(145);p.attackAnim=.28;if(target){this.g.world.addEffect({type:'slash',x:p.x,y:p.y,a:p.facing,radius:45,life:.22});this.hitEnemy(target,p.damage*(this.buff>0?1.35:1),Math.random()<p.crit)}else this.g.world.addEffect({type:'slash',x:p.x,y:p.y,a:p.facing,radius:36,life:.18})}
 useSkill(i){let p=this.g.player,c=this.cooldowns;if(i<0||i>5||c[i]>0||this.g.paused||this.g.dead)return;let rank=p.level, costs=[0,0,10,14,20,28], cost=costs[i];if(p.resource<cost){this.g.ui.toast('Not enough '+(this.g.class.resource||'resource').toLowerCase()+'.');return}p.resource-=cost;c[i]=[.45,.8,4,7,10,16][i];let w=this.g.world,t=this.nearest(420),d=p.damage*(1+[.25,.4,.7,0,1.15,1.65][i]+rank*.025),klass=p.classId;
 if(i===3||i===5&&['warrior','mage','ranger','necromancer','paladin','assassin'].includes(klass)){this.buff=4;if(i===5){p.hp=Math.min(p.maxHp,p.hp+Math.round(p.maxHp*.18));p.invuln=1.2}w.addEffect({type:'burst',x:p.x,y:p.y,radius:95,color:'#d5b16b',life:.55});this.g.ui.toast(i===3?'Your resolve hardens.':'A fragment of power answers.',true);return}
 if(i===1&&['mage','paladin','necromancer'].includes(klass)){w.addEffect({type:'burst',x:p.x,y:p.y,radius:115,color:klass==='mage'?'#86b9e3':'#d6c58d',life:.5});w.entities.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<115).forEach(e=>{this.hitEnemy(e,d*.8,Math.random()<p.crit);e.slow=2});return}
 if(i===2&&t){let dx=t.x-p.x,dy=t.y-p.y,n=Math.hypot(dx,dy)||1;w.addEffect({type:'beam',x:p.x,y:p.y,x2:t.x,y2:t.y,width:6,color:'#c8d4e4',life:.28});w.entities.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<220).slice(0,4).forEach(e=>this.hitEnemy(e,d*.7,false));return}
 if(i===4){w.addEffect({type:'burst',x:p.x,y:p.y,radius:170,color:'#d9a95e',life:.7});w.entities.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<170).forEach(e=>this.hitEnemy(e,d,false));return}
 if(t){let dx=t.x-p.x,dy=t.y-p.y,n=Math.hypot(dx,dy)||1;w.projectiles.push({x:p.x,y:p.y,vx:dx/n*420,vy:dy/n*420,life:1.1,speed:420,radius:11,damage:d,crit:Math.random()<p.crit,color:klass==='mage'?'#8dc2ee':'#e0b56d'})}else if(i===0||i===1){w.addEffect({type:'burst',x:p.x+Math.cos(p.facing)*65,y:p.y+Math.sin(p.facing)*65,radius:80,color:'#d5ac71',life:.42});w.entities.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<105).forEach(e=>this.hitEnemy(e,d*.78,false))}
 }
 hitEnemy(e,damage,critical=false){if(!e.alive)return;let p=this.g.player;let amt=Math.max(1,Math.round(damage*(critical?1.7:1)));e.hp-=amt;e.hitFlash=.14;this.g.world.addEffect({type:'impact',x:e.x,y:e.y-18,color:critical?'#f4d18c':'#efe0c6',life:.18});this.g.ui.damageNumber(e.x,e.y,amt,critical);if(e.hp<=0){e.alive=false;e.deadT=0;let d=this.g.world.dropFor(e);p.xp+=e.type==='boss'?580:e.type==='elite'?95:e.type==='cultist'?22:e.type==='hound'?16:18;p.gold+=e.type==='boss'?80:Math.floor(2+Math.random()*8);p.essence+=e.type==='boss'?8:1;this.g.progression.checkLevel();this.g.ui.onKill(e);if(Math.random()<.32||e.type==='elite'||e.type==='boss')this.g.inventory.addDrop(d)} }
 hitPlayer(damage,enemy){let p=this.g.player;if(p.invuln>0||this.g.dead)return;let nearby=this.g.world.entities.filter(e=>e.alive&&Math.hypot(e.x-p.x,e.y-p.y)<150).length;let reduction=Math.min(.2,nearby*.04)+(p.armor||0)/100;let amt=Math.max(1,Math.round(damage*(1-reduction)));p.hp-=amt;p.invuln=.45;this.g.ui.damageNumber(p.x,p.y-25,amt,true);if(p.hp<=0){p.hp=0;this.g.dead=true;this.g.ui.showDeath()}}
 update(dt){this.cooldowns=this.cooldowns.map(x=>Math.max(0,x-dt));this.buff=Math.max(0,this.buff-dt);let p=this.g.player;p.resource=Math.min(p.maxResource,p.resource+dt*(p.classId==='warrior'?3:5))}
}

